{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-PwoWs5/src/address.js","content":"/**
 * Cell-address helpers shared by sheet parsing, formula evaluation, and
 * dependency collection. An address is one or two letters (A-Z, upper-cased)
 * naming a column, followed by one to three digits naming a row of at
 * least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses a word as a cell address. Returns null when the word is not
 * shaped like an address, or names a row of 0 (row values below 1 are
 * outside the addressable range even though the digit count matches).
 */
export function parseAddressWord(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { letters, row, col: colLettersToNum(letters), key: letters + String(row) }
}

export function colLettersToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colNumToLetters(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Resolves a range given by its two corner words, expanding to every cell
 * it covers in ascending column and then ascending row order. Returns null
 * when either corner is not a valid address.
 */
export function resolveRange(fromWord, toWord) {
  const from = parseAddressWord(fromWord)
  const to = parseAddressWord(toWord)
  if (!from || !to) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    const letters = colNumToLetters(c)
    for (let r = rowMin; r <= rowMax; r++) cells.push(letters + String(r))
  }
  return cells
}

/** Orders address keys (e.g. "A1", "AA23") by column then row. */
export function compareAddressKeys(a, b) {
  const pa = parseAddressWord(a)
  const pb = parseAddressWord(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

