{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-PwoWs5/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<>', '<=', '>=']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

/** Splits a formula body into a token list terminated by an EOF token. */
export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (j < n && src[j] === '.' && j + 1 < n && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: src.slice(i, j) })
      i = j
      continue
    }
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      let j = i + 1
      while (j < n && ((src[j] >= 'A' && src[j] <= 'Z') || (src[j] >= 'a' && src[j] <= 'z'))) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'IDENT', value: src.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    const two = src.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

