 * Value representation shared by literal parsing and formula evaluation.
 * A value is one of: a number, text, a boolean, or an error token.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const ERR_DIV0 = err('#DIV/0!')
export const ERR_REF = err('#REF!')
export const ERR_VALUE = err('#VALUE!')
export const ERR_CYCLE = err('#CYCLE!')
export const ERR_NAME = err('#NAME?')
export const ERR_ERR = err('#ERR!')

/** Parses literal (non-formula) cell content into a value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (/^-?\d+(\.\d+)?$/.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** Reads a value as a number in an arithmetic position. */
export function toNumber(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return ERR_VALUE
}

/** Wraps an arithmetic result, turning any non-finite result into #DIV/0!. */
export function finiteOrDiv0(n) {
  return Number.isFinite(n) ? num(n) : ERR_DIV0
}

function rankOf(v) {
  return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2
}

/** Compares two non-error values per the cross-kind ordering rules. */
export function compareValues(l, r) {
  if (l.t !== r.t) return rankOf(l) - rankOf(r)
  if (l.t === 'num') return l.v - r.v
  if (l.t === 'text') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  return (l.v ? 1 : 0) - (r.v ? 1 : 0)
}

/** Rounds a finite number to ten significant digits and formats it as JS would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

export function formatValue(v) {
  switch (v.t) {
    case 'num':
      return formatNumber(v.v)
    case 'text':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'err':
      return v.v
  }
}
"}

