 * Evaluates a parsed sheet: cell values are computed lazily and memoized,
 * with cycle detection via a per-cell in-progress marker.
 */

import { parseAddressWord, resolveRange } from './address.js'
import { parseFormula } from './parser.js'
import { num, bool, err, text, toNumber, finiteOrDiv0, compareValues, parseLiteral, ERR_REF, ERR_VALUE, ERR_ERR, ERR_NAME, ERR_CYCLE } from './values.js'

const VARIADIC_FUNCTIONS = ['SUM', 'MIN', 'MAX', 'AVG', 'COUNT']
const KNOWN_FUNCTIONS = [...VARIADIC_FUNCTIONS, 'ABS', 'IF']

const COMPARATORS = {
  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

/** Builds an evaluation context over a parsed sheet (Map of address key -> content). */
export function createEvaluator(sheet) {
  const cache = new Map()
  const state = new Map() // 'in-progress' | 'done'

  function getCellValue(key) {
    if (cache.has(key)) return cache.get(key)
    if (state.get(key) === 'in-progress') return err('#CYCLE!')
    const content = sheet.get(key)
    if (content === undefined) {
      const v = num(0)
      cache.set(key, v)
      return v
    }
    state.set(key, 'in-progress')
    const v = evalContent(content)
    state.set(key, 'done')
    cache.set(key, v)
    return v
  }

  function evalContent(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast) return ERR_ERR
      return evalNode(ast)
    }
    return parseLiteral(content)
  }

  function evalRef(word) {
    const info = parseAddressWord(word)
    if (!info) return ERR_REF
    return getCellValue(info.key)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref':
        return evalRef(node.word)
      case 'unary':
        return evalUnary(node)
      case 'binop':
        return evalBinop(node)
      case 'call':
        return evalCall(node)
      default:
        return ERR_ERR
    }
  }

  function evalUnary(node) {
    const v = toNumber(evalNode(node.operand))
    if (v.t === 'err') return v
    return finiteOrDiv0(node.op === '-' ? -v.v : v.v)
  }

  function evalBinop(node) {
    const l = evalNode(node.left)
    const r = evalNode(node.right)
    if (COMPARATORS[node.op]) {
      if (l.t === 'err') return l
      if (r.t === 'err') return r
      const c = compareValues(l, r)
      return bool(COMPARATORS[node.op](c))
    }
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    const ln = toNumber(l)
    if (ln.t === 'err') return ln
    const rn = toNumber(r)
    if (rn.t === 'err') return rn
    switch (node.op) {
      case '+':
        return finiteOrDiv0(ln.v + rn.v)
      case '-':
        return finiteOrDiv0(ln.v - rn.v)
      case '*':
        return finiteOrDiv0(ln.v * rn.v)
      case '/':
        return rn.v === 0 ? err('#DIV/0!') : finiteOrDiv0(ln.v / rn.v)
      case '^':
        return finiteOrDiv0(Math.pow(ln.v, rn.v))
      default:
        return ERR_ERR
    }
  }

  /** Evaluates a single argument that may be a range, requiring exactly one resulting value. */
  function evalArgScalar(argNode) {
    if (argNode.type !== 'range') return evalNode(argNode)
    const cells = resolveRange(argNode.from, argNode.to)
    if (!cells) return ERR_REF
    const values = cells.map(getCellValue)
    for (const v of values) if (v.t === 'err') return v
    if (values.length !== 1) return ERR_ERR
    return values[0]
  }

  /** Expands a list of argument nodes into a flat list of values, ranges expanded. */
  function expandArgList(argNodes) {
    const values = []
    for (const a of argNodes) {
