        }
        for (const key of cells) values.push(getCellValue(key))
      } else {
        values.push(evalNode(a))
      }
    }
    return values
  }

  function evalCall(node) {
    if (!KNOWN_FUNCTIONS.includes(node.name)) return ERR_NAME
