    if (node.args.length !== 1) return ERR_ERR
    const v = toNumber(evalArgScalar(node.args[0]))
    if (v.t === 'err') return v
    return finiteOrDiv0(Math.abs(v.v))
  }

  function evalVariadic(node) {
    if (node.args.length < 1) return ERR_ERR
    const values = expandArgList(node.args)
    if (node.name === 'COUNT') {
      for (const v of values) if (v.t === 'err') return v
      return num(values.filter((v) => v.t === 'num').length)
    }
    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.t === 'err') return n
      nums.push(n.v)
    }
    switch (node.name) {
