      case 'MAX':
        return finiteOrDiv0(Math.max(...nums))
      case 'AVG':
        return finiteOrDiv0(nums.reduce((a, b) => a + b, 0) / nums.length)
      default:
        return ERR_ERR
    }
  }

  return { getCellValue }
}
