 * Collects the addresses a formula names directly, independent of what any
 * cell evaluates to: ranges expand to every cell they cover, and only
 * addresses inside the addressable range are named.
 */

import { parseAddressWord, resolveRange, compareAddressKeys } from './address.js'
import { parseFormula } from './parser.js'

function collect(node, keys) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'unary':
      collect(node.operand, keys)
      return
    case 'binop':
      collect(node.left, keys)
      collect(node.right, keys)
      return
    case 'ref': {
      const info = parseAddressWord(node.word)
      if (info) keys.add(info.key)
      return
    }
    case 'call':
      for (const arg of node.args) collectArg(arg, keys)
      return
  }
}

function collectArg(arg, keys) {
  if (arg.type === 'range') {
    const cells = resolveRange(arg.from, arg.to)
    if (cells) for (const key of cells) keys.add(key)
    return
  }
  collect(arg, keys)
}

/** Returns the sorted list of address keys a cell's content names directly. */
export function directDeps(content) {
  if (!content.startsWith('=')) return []
  const ast = parseFormula(content.slice(1))
  if (!ast) return []
  const keys = new Set()
  collect(ast, keys)
  return [...keys].sort(compareAddressKeys)
}
