/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { compareAddressKeys } from './address.js'
import { createEvaluator } from './evaluator.js'
import { formatValue } from './values.js'
import { directDeps } from './deps.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }

  const source = readStdin()

  let sheet
  try {
    sheet = parseSheet(source)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const sortedKeys = [...sheet.order].sort(compareAddressKeys)
  const out = []

  if (mode === 'values') {
    const evaluator = createEvaluator(sheet.contents)
    for (const key of sortedKeys) {
      const value = evaluator.getCellValue(key)
      out.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const key of sortedKeys) {
      const deps = directDeps(sheet.contents.get(key))
      out.push(deps.length === 0 ? `${key}:` : `${key}: ${deps.join(' ')}`)
